+//
+// Strategy: hybrid MSD radix sort on the top 8 bits, then recurse on buckets.
+// For small buckets (<= 64) use insertion sort. Extra scratch buffer allocated once.
+
+static void insertion_sort(uint32_t* a, size_t n) {
+    for (size_t i = 1; i < n; ++i) {
+        uint32_t v = a[i];
+        size_t j = i;
+        while (j > 0 && a[j - 1] > v) {
+            a[j] = a[j - 1];
+            --j;
+        }
+        a[j] = v;
+    }
+}
+
+// MSD radix sort on bits [hi_bit, hi_bit+8). Recurses into each non-empty bucket.
+static void msd_radix_sort(uint32_t* a, uint32_t* buf, size_t n, int hi_bit) {
+    if (n <= 1) return;
+    if (n <= 64) { insertion_sort(a, n); return; }
+    if (hi_bit < 0) return;  // all equal
+
+    // Count frequencies for the 8-bit digit at position hi_bit
+    uint32_t counts[256];
+    memset(counts, 0, sizeof(counts));
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t digit = (a[i] >> hi_bit) & 0xFF;
+        ++counts[digit];
+    }
+
+    // Compute exclusive prefixes
+    uint32_t pos[256];
+    uint32_t sum = 0;
+    for (int d = 0; d < 256; ++d) {
+        pos[d] = sum;
+        sum += counts[d];
+    }
+
+    // Scatter into buffer
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t digit = (a[i] >> hi_bit) & 0xFF;
+        buf[pos[digit]++] = a[i];
+    }
+
+    // Copy back and recurse into non-singleton buckets
+    memcpy(a, buf, n * sizeof(uint32_t));
+    size_t offset = 0;
+    for (int d = 0; d < 256; ++d) {
+        uint32_t bucket_size = counts[d];
+        if (bucket_size > 1) {
+            msd_radix_sort(a + offset, buf, bucket_size, hi_bit - 8);
+        }
+        offset += bucket_size;
+    }
 }

